const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.book}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();const fmt=d=>new Date(d).toLocaleDateString('zh-CN',{month:'long',day:'numeric'});const dateISO=offset=>{const d=new Date();d.setDate(d.getDate()+offset);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const seed=()=>({tasks:[{id:'t1',title:'让第一盏 LED 亮起来',category:'智能硬件入门',due:dateISO(2),body:'用开发板点亮一盏 LED，并尝试让它按照不同的节奏闪烁。\n\n学习目标\n1. 认识数字输出与引脚。\n2. 理解程序中的循环和延时。\n3. 完成接线并记录调试过程。\n\n提交要求\n提交代码文件或接线照片，并用文字说明遇到的问题和解决方法。',submissions:[]},{id:'t2',title:'设计你的智能校园小助手',category:'创意实践',due:dateISO(4),body:'观察校园生活，提出一个可以用智能硬件解决的小问题。\n\n请描述使用场景、需要的传感器，以及预期的工作流程。可以附上手绘草图。',submissions:[]},{id:'t3',title:'温湿度传感器：读懂身边的环境',category:'传感器探索',due:dateISO(6),body:'连接温湿度传感器，记录三个不同位置的环境数据。\n\n整理数据，解释差异，并提交代码和实验记录。',submissions:[{id:'s1',user:'student',name:'林同学',text:'已经完成三个地点的温湿度测量，教室内的温度更稳定。',files:[],time:new Date().toISOString(),status:'需修改',feedback:'实验过程很清楚！请补充三组具体数据，以及测量时的时间和位置。'}]}],posts:[{id:'p1',title:'欢迎来到知行社，一起把想法变成现实 🌱',body:'新学期，我们会一起探索编程与智能硬件的世界。这里可以分享你的新发现、记录调试中的小问题，也欢迎帮助遇到困难的伙伴。\n第一步：在评论区介绍一下自己，以及你最想做的一个小项目吧！',author:'陈老师',user:'teacher',teacher:true,category:'社团日常',pinned:true,time:new Date().toISOString(),likes:[],comments:[{id:'c1',user:'xiaozhou',name:'周同学',body:'我想做一个能提醒植物浇水的小装置！',time:new Date().toISOString()}]},{id:'p2',title:'分享一个小技巧：接线之前先画一张草图',body:'今天接线的时候发现，先把引脚对应关系画在纸上，真的会少走很多弯路。大家有没有自己的调试小技巧？欢迎一起交流～',author:'周同学',user:'xiaozhou',teacher:false,category:'学习分享',pinned:false,time:new Date().toISOString(),likes:[],comments:[]},{id:'p3',title:'我的 LED 一直亮着不闪烁，可能是什么原因？',body:'程序能够上传，但 LED 一直亮着。我检查了引脚编号，还是没找到原因，有没有同学遇到过类似的问题？',author:'林同学',user:'student',teacher:false,category:'提问求助',pinned:false,time:new Date().toISOString(),likes:[],comments:[]}],announcements:[{id:'a1',title:'本周社团活动提醒：带上你的开发板，我们一起探索智能硬件',body:'本周活动将在创客教室进行。请提前准备好开发板、USB 数据线和笔记本电脑。\n\n第一次参加的同学可以提前 10 分钟到场，老师会协助安装开发环境。期待大家的奇思妙想！',time:new Date().toISOString(),pinned:true}],profiles:{student:{name:'林同学',className:'智能硬件社 · 入门组',bio:'保持好奇，动手探索。'},teacher:{name:'陈老师',className:'智能硬件社 · 指导教师',bio:'陪伴每一个创意生长。'}}});
let data;try{data=JSON.parse(localStorage.getItem('zhixing-v1'))||seed()}catch{data=seed()}
let role=sessionStorage.getItem('zhixing-role')||'',taskFilter='待办',postFilter='全部帖子',query='',nav='home';
const user=()=>role==='teacher'?'teacher':'student';const profile=()=>data.profiles[user()];const isTeacher=()=>role==='teacher';
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',2800)}
function save(){try{localStorage.setItem('zhixing-v1',JSON.stringify(data));return true}catch{toast('浏览器存储空间不足，请减少附件大小后重试');return false}}
function submission(t){return t.submissions.filter(s=>s.user===user()).at(-1)}
function status(t){return submission(t)?.status||'待提交'}
const statusClass=s=>s==='已完成'?'done':s==='待评价'?'review':s==='需修改'?'revise':'';
const pending=()=>data.tasks.filter(t=>['待提交','需修改'].includes(status(t))).length;
function closeModal(){ $('#overlay').innerHTML='';document.body.style.overflow='';document.removeEventListener('keydown',modalKey);window.modalFocus?.focus() }
function modalKey(e){if(e.key==='Escape')closeModal();if(e.key==='Tab'){const nodes=[...document.querySelectorAll('.modal button,.modal input,.modal textarea,.modal select,.modal a')].filter(n=>!n.disabled);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}}
function modal(title,body){window.modalFocus=document.activeElement;$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="close" data-action="close" aria-label="关闭">×</button></div><div class="modal-body">${body}</div></section></div>`;document.body.style.overflow='hidden';document.addEventListener('keydown',modalKey);$('.modal .close').focus()}
function login(){ $('#app').innerHTML=`<div class="login-screen"><div class="login-art"><div class="eyebrow">ZHIXING CLUB / LEARN BY DOING</div><h1>保持好奇，<br>让想法发生。</h1><p>从一盏小灯，到一个有趣的发明。<br>和志同道合的伙伴一起，在实践中成长。</p></div><div class="login-box"><div class="login-inner"><div class="brand"><div class="brand-mark">${icon('leaf')}</div><div>知行社<small>ZHIXING CLUB</small></div></div><h2>欢迎来到你的学习空间</h2><p>选择一个身份，开始体验第一版。</p><button class="role-choice" data-action="login" data-id="student">${icon('book')}<div><strong>我是学生</strong><small>查看任务、提交成果、和伙伴交流</small></div>${icon('arrow')}</button><button class="role-choice" data-action="login" data-id="teacher">${icon('users')}<div><strong>我是指导教师</strong><small>发布任务、评价提交、管理社团动态</small></div>${icon('arrow')}</button><p>演示模式 · 使用示例身份，无需密码。<br>数据保存在此浏览器，暂不支持多人同步。</p></div></div></div>` }
function calendar(){const now=new Date(),year=now.getFullYear(),month=now.getMonth(),start=(new Date(year,month,1).getDay()+6)%7,days=new Date(year,month+1,0).getDate();return `<div class="panel right-panel"><div class="right-head">学习日历<span class="calendar-head">${year} 年 ${month+1} 月</span></div><div class="calendar-grid">${['一','二','三','四','五','六','日'].map(d=>`<span class="weekday">${d}</span>`).join('')}${'<span></span>'.repeat(start)}${Array.from({length:days},(_,i)=>`<span class="${i+1===now.getDate()?'today':data.tasks.some(t=>{const d=new Date(t.due);return d.getFullYear()===year&&d.getMonth()===month&&d.getDate()===i+1})?'due':''}">${i+1}</span>`).join('')}</div><div class="calendar-note"><i class="dot"></i>任务截止日期</div></div>`}
function render(){if(!role){login();return}const p=profile(),teacher=isTeacher(),notices=[...data.announcements].sort((a,b)=>Number(b.pinned)-Number(a.pinned)||b.time.localeCompare(a.time)),n=notices[0],reviewCount=data.tasks.reduce((n,t)=>n+t.submissions.filter(s=>s.status==='待评价').length,0);$('#app').innerHTML=`<aside class="sidebar"><div class="brand"><div class="brand-mark">${icon('leaf')}</div><div>知行社<small>ZHIXING CLUB</small></div></div><div class="nav-label">我的学习空间</div><button class="nav ${nav==='home'?'active':''}" data-action="nav" data-id="home">${icon('home')}<span>个人空间</span></button><button class="nav ${nav==='tasks'?'active':''}" data-action="nav" data-id="tasks">${icon('task')}<span>${teacher?'任务管理':'我的任务'}</span><span class="count">${teacher?reviewCount:pending()}</span></button><button class="nav ${nav==='posts'?'active':''}" data-action="nav" data-id="posts">${icon('post')}<span>帖子中心</span></button>${teacher?`<button class="nav" data-action="announcements">${icon('bell')}<span>公告管理</span></button>`:''}<div class="sidebar-bottom"><div class="club-card"><strong>一起探索，一起成长</strong><p>智能硬件社 · 秋季学习计划</p><div class="mini-members"><span>陈</span><span>林</span><span>周</span><small>我们的学习小组</small></div></div><button class="nav" data-action="logout">${icon('logout')}<span>退出体验</span></button><div class="side-footer">知行合一 · 学以致用</div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">我的社团 <span>/</span> <b>${nav==='tasks'?'我的任务':nav==='posts'?'帖子中心':'个人空间'}</b></div><div class="top-actions"><span class="demo-label">首版体验 · 本地数据</span><button data-action="announcements" aria-label="查看公告">${icon('bell')}</button><button class="user-btn" data-action="profile"><div class="avatar">${esc(p.name[0])}</div><span>${esc(p.name)}</span><span>⌄</span></button></div></header><div class="content"><section class="welcome"><div><div class="eyebrow">MY LEARNING SPACE</div><h1>${esc(p.name)}，${new Date().getHours()<12?'上午好':new Date().getHours()<18?'下午好':'晚上好'} <span style="font-size:23px">☀</span></h1><p>${teacher?'每一次用心的指导，都在帮助一个想法生长。':'新的一天，从一个小小的探索开始。'}</p></div><div class="date">${icon('calendar')}${new Date().toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'long'})}</div></section>${n?`<section class="notice">${icon('bell')}<span class="notice-badge">${n.pinned?'置顶公告':'社团公告'}</span><button class="notice-title" data-action="notice" data-id="${n.id}">${esc(n.title)}</button><span class="notice-time">${fmt(n.time)}</span><button class="notice-more" data-action="announcements">全部公告 →</button></section>`:''}<div class="columns"><div>${nav!=='posts'?taskPanel():''}${nav!=='tasks'?postPanel():''}</div><aside class="right-column"><section class="profile"><div class="avatar large-avatar">${esc(p.name[0])}</div><h3>${esc(p.name)}</h3><p>${esc(p.className)}</p><span class="member-tag">${teacher?'指导教师':'探索中的创客'}</span><div class="stats"><div><strong>${teacher?data.tasks.length:data.tasks.filter(t=>status(t)==='已完成').length}</strong><small>${teacher?'已发布任务':'已完成任务'}</small></div><div><strong>${data.posts.filter(x=>x.user===user()).length}</strong><small>发布帖子</small></div><div><strong>${teacher?reviewCount:pending()}</strong><small>${teacher?'待评价提交':'待办任务'}</small></div></div></section>${calendar()}<section class="panel tip">${icon('leaf')}<span class="tip-art">✧</span><h4>进步，藏在每一次尝试里</h4><p>遇到问题不用着急，在帖子中心记录你的尝试，和伙伴一起寻找答案。</p></section></aside></div><footer class="page-footer">知行社 · 让每一个想法，都有生长的空间</footer></div></main>`}
function taskPanel(){let list=data.tasks;if(!isTeacher())list=list.filter(t=>taskFilter==='全部'||(taskFilter==='待办'?['待提交','需修改'].includes(status(t)):status(t)===taskFilter));return `<section class="panel"><div class="panel-head"><div class="section-title">${icon('task')}${isTeacher()?'教学任务':'待办任务'}<small>${data.tasks.length} 项任务</small></div>${isTeacher()?`<button class="primary" data-action="new-task">${icon('plus')}发布任务</button>`:`<button class="text-button" data-action="all-tasks">查看全部 →</button>`}</div><div class="tabs">${(isTeacher()?['全部']:['待办','待评价','已完成','全部']).map(f=>`<button class="tab ${taskFilter===f||isTeacher()?'active':''}" data-action="task-filter" data-id="${f}">${f}${f==='待办'?`<small>${pending()}</small>`:''}</button>`).join('')}</div><div class="tasks">${list.map(t=>{const s=status(t),cnt=t.submissions.filter(x=>x.status==='待评价').length;return `<article class="task"><div class="task-icon">${icon('book')}</div><div class="task-body"><button class="task-title" data-action="task" data-id="${t.id}">${esc(t.title)}</button><div class="task-meta"><span class="tag">${esc(t.category)}</span><span>${fmt(t.due)} 截止</span>${new Date(`${t.due}T23:59:59`)<new Date()?'<span class="danger">已逾期</span>':''}</div></div><span class="status ${statusClass(s)}">${isTeacher()?`${cnt} 份待评价`:s}</span><button class="task-action" data-action="task" data-id="${t.id}">${isTeacher()?'查看提交':s==='待提交'?'去完成':s==='需修改'?'去修改':'查看详情'}</button></article>`}).join('')||'<div class="empty">这里暂时没有任务，去帖子中心看看吧。</div>'}</div><div class="panel-bottom">${isTeacher()?'以实践启发思考，用反馈陪伴成长':'每完成一个小任务，都离自己的创意更近一步'}</div></section>`}
function postPanel(){let list=data.posts.filter(p=>(postFilter!=='我的帖子'||p.user===user())&&(!query||(p.title+p.body).toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>Number(b.pinned)-Number(a.pinned)||b.time.localeCompare(a.time));return `<section class="panel"><div class="panel-head"><div class="section-title">${icon('post')}帖子中心<small>交流 · 分享 · 发现</small></div><button class="primary" data-action="new-post">${icon('plus')}发布帖子</button></div><div class="post-tools"><div class="tabs">${['全部帖子','我的帖子'].map(f=>`<button class="tab ${postFilter===f?'active':''}" data-action="post-filter" data-id="${f}">${f}</button>`).join('')}</div><label class="search">${icon('search')}<input id="search" aria-label="搜索帖子" placeholder="搜索帖子" value="${esc(query)}"></label></div><div>${list.map(p=>`<article class="post"><div class="post-user"><div class="avatar" style="background:${p.teacher?'#e0e9d5':'#eee6d5'}">${esc(p.author[0])}</div><span>${esc(p.author)}</span>${p.teacher?'<span class="teacher-tag">指导教师</span>':''}<small>· ${fmt(p.time)}</small></div><button class="post-title" data-action="post" data-id="${p.id}">${p.pinned?'<span class="tag" style="margin-right:7px;color:#69916e">置顶</span>':''}${esc(p.title)}</button><p class="post-excerpt">${esc(p.body.slice(0,110))}${p.body.length>110?'…':''}</p><div class="post-footer"><div class="tags"><span class="tag"># ${esc(p.category)}</span></div><div class="post-count"><button data-action="like" data-id="${p.id}" aria-label="点赞" style="color:${p.likes.includes(user())?'#187567':''}">${icon('like')}${p.likes.length}</button><button data-action="post" data-id="${p.id}" aria-label="查看评论">${icon('post')}${p.comments.length}</button></div></div></article>`).join('')||'<div class="empty">暂时没有相关帖子，分享你的第一个想法吧。</div>'}</div></section>`}
function fileHTML(files){return (files||[]).map((f,i)=>`<div class="attached">附件：<button class="file-link" data-action="download" data-id="${f.id}">${esc(f.name)}</button> <small>${Math.ceil(f.size/1024)} KB</small></div>`).join('')}
async function readFiles(input){const files=[...(input.files||[])];if(files.length>3)throw Error('每次最多上传 3 个附件');if(files.some(f=>f.size>500*1024))throw Error('演示版每个附件最大 500 KB');return Promise.all(files.map(f=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve({id:uid(),name:f.name,size:f.size,data:r.result});r.onerror=()=>reject(Error('附件读取失败'));r.readAsDataURL(f)})))}
function openTask(id){const t=data.tasks.find(t=>t.id===id);if(!t)return;const s=submission(t);modal('任务详情',`<span class="tag">${esc(t.category)}</span><h2>${esc(t.title)}</h2><div class="muted">截止时间：${esc(t.due)} 23:59</div><p>${esc(t.body)}</p>${isTeacher()?`<div class="form-actions"><button class="secondary" data-action="edit-task" data-id="${id}">编辑任务</button></div><h3>学生提交 · ${t.submissions.length} 份</h3>${t.submissions.map(s=>`<div class="submission"><h4>${esc(s.name)} <span class="status ${statusClass(s.status)}">${s.status}</span></h4><div class="muted">${new Date(s.time).toLocaleString('zh-CN')}</div><p>${esc(s.text)}</p>${fileHTML(s.files)}${s.feedback?`<div class="info-box">教师反馈：${esc(s.feedback)}</div>`:''}<button class="secondary" data-action="review" data-id="${id}:${s.id}">评价此提交</button></div>`).join('')||'<div class="empty">暂时没有学生提交</div>'}`:`${s?`<h3>最近一次提交</h3><div class="submission"><span class="status ${statusClass(s.status)}">${s.status}</span><p>${esc(s.text)}</p>${fileHTML(s.files)}<div class="muted">${new Date(s.time).toLocaleString('zh-CN')}</div>${s.feedback?`<div class="info-box">老师反馈：${esc(s.feedback)}</div>`:''}</div>`:''}<form id="submit-task" data-id="${id}"><label for="submission-text">${s?'更新提交内容':'我的提交'}</label><textarea id="submission-text" name="text" placeholder="介绍你的成果、遇到的问题和解决方法…" maxlength="10000" required>${esc(s?.text||localStorage.getItem('draft-'+id)||'')}</textarea><label for="task-files">添加附件</label><input id="task-files" name="files" type="file" multiple><div class="muted">最多 3 个附件，每个不超过 500 KB；未选择新附件时保留上次附件。</div><div class="form-actions"><button type="button" class="secondary" data-action="draft" data-id="${id}">保存草稿</button><button class="primary" type="submit">${s?'重新提交':'提交任务'}</button></div></form>${t.submissions.filter(x=>x.user===user()).length>1?`<h3>历史提交</h3>${t.submissions.filter(x=>x.user===user()).slice(0,-1).reverse().map(x=>`<div class="submission"><div class="muted">${new Date(x.time).toLocaleString('zh-CN')} · ${esc(x.status)}</div><p>${esc(x.text)}</p>${fileHTML(x.files)}${x.feedback?`<div class="info-box">${esc(x.feedback)}</div>`:''}</div>`).join('')}`:''}`}`)}
function taskForm(id){const t=data.tasks.find(t=>t.id===id);modal(t?'编辑任务':'发布新任务',`<form id="task-form" data-id="${t?.id||''}"><label>任务标题<input name="title" value="${esc(t?.title||'')}" required maxlength="100"></label><label>任务分类<input name="category" value="${esc(t?.category||'实践任务')}" required maxlength="30"></label><label>截止日期<input name="due" type="date" value="${t?.due||dateISO(7)}" required></label><label>任务说明与参考资料<textarea name="body" required maxlength="10000" placeholder="写清学习目标、操作步骤与提交要求，可以包含参考链接。">${esc(t?.body||'')}</textarea></label><div class="form-actions"><button type="button" class="secondary" data-action="close">取消</button><button class="primary">${t?'保存修改':'发布任务'}</button></div></form>`)}
function openPost(id){const p=data.posts.find(p=>p.id===id);if(!p)return;modal('帖子详情',`<span class="tag">${esc(p.category)}</span><h2>${esc(p.title)}</h2><div class="muted">${esc(p.author)} · ${fmt(p.time)}</div><p class="post-body-full">${esc(p.body)}</p>${fileHTML(p.files)}<div class="form-actions"><button class="secondary" data-action="like-modal" data-id="${id}">${p.likes.includes(user())?'取消点赞':'点赞'} · ${p.likes.length}</button>${isTeacher()?`<button class="secondary" data-action="pin" data-id="${id}">${p.pinned?'取消置顶':'置顶帖子'}</button>`:''}${p.user===user()?`<button class="secondary" data-action="edit-post" data-id="${id}">编辑</button>`:''}${p.user===user()||isTeacher()?`<button class="secondary danger" data-action="delete-post" data-id="${id}">删除</button>`:''}</div><h3>交流讨论 · ${p.comments.length}</h3>${p.comments.map(c=>`<div class="comment"><strong>${esc(c.name)}</strong><p>${esc(c.body)}</p><div class="muted">${fmt(c.time)} ${c.user===user()||isTeacher()?`<button class="danger" data-action="delete-comment" data-id="${id}:${c.id}">删除</button>`:''}</div></div>`).join('')||'<div class="muted">还没有评论，来开启交流吧。</div>'}<form id="comment-form" data-id="${id}"><label for="comment">写下你的想法</label><textarea id="comment" name="body" required maxlength="2000" placeholder="友善交流，让灵感碰撞…"></textarea><div class="form-actions"><button class="primary">发表评论</button></div></form>`)}
function postForm(id){const p=data.posts.find(p=>p.id===id);modal(p?'编辑帖子':'分享一个新想法',`<form id="post-form" data-id="${p?.id||''}"><label>帖子标题<input name="title" required maxlength="100" value="${esc(p?.title||'')}" placeholder="你想分享或讨论什么？"></label><label>分类<select name="category">${['学习分享','提问求助','社团日常'].map(c=>`<option ${p?.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label>正文<textarea name="body" required maxlength="10000" placeholder="记录你的探索，或者向伙伴提出一个问题…">${esc(p?.body||'')}</textarea></label><label>图片或附件<input name="files" type="file" multiple></label><div class="muted">最多 3 个附件，每个不超过 500 KB。未选新附件时保留原附件。</div><div class="form-actions"><button type="button" class="secondary" data-action="close">取消</button><button class="primary">${p?'保存修改':'发布帖子'}</button></div></form>`)}
function announcements(){modal(isTeacher()?'公告管理':'社团公告',`${isTeacher()?'<button class="primary" data-action="new-notice">＋ 发布公告</button>':''}${[...data.announcements].sort((a,b)=>Number(b.pinned)-Number(a.pinned)||b.time.localeCompare(a.time)).map(n=>`<div class="submission"><button class="task-title" data-action="notice" data-id="${n.id}">${n.pinned?'📌 ':''}${esc(n.title)}</button><div class="muted">${fmt(n.time)}</div><p>${esc(n.body.slice(0,80))}</p>${isTeacher()?`<button class="secondary" data-action="edit-notice" data-id="${n.id}">编辑</button> <button class="secondary danger" data-action="delete-notice" data-id="${n.id}">删除</button>`:''}</div>`).join('')||'<p class="empty">暂时没有公告</p>'}`)}
function noticeForm(id){const n=data.announcements.find(n=>n.id===id);modal(n?'编辑公告':'发布公告',`<form id="notice-form" data-id="${n?.id||''}"><label>标题<input name="title" required maxlength="100" value="${esc(n?.title||'')}"></label><label>公告内容<textarea name="body" required maxlength="10000">${esc(n?.body||'')}</textarea></label><label>显示方式<select name="pinned"><option value="true" ${n?.pinned?'selected':''}>置顶公告</option><option value="false" ${n&&!n.pinned?'selected':''}>普通公告</option></select></label><div class="form-actions"><button class="primary">发布公告</button></div></form>`)}
function confirmDelete(title,action,id){modal('确认删除',`<p>确定删除${esc(title)}？删除后无法恢复。</p><div class="form-actions"><button class="secondary" data-action="close">取消</button><button class="primary" data-action="${action}" data-id="${id}">确认删除</button></div>`)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;const teacherActions=['new-task','edit-task','review','pin','new-notice','edit-notice','delete-notice','confirm-notice-delete'];if(teacherActions.includes(a)&&!isTeacher())return;
if(a==='close')closeModal();if(a==='login'){role=id;sessionStorage.setItem('zhixing-role',id);nav='home';render()}if(a==='logout'){role='';sessionStorage.removeItem('zhixing-role');render()}if(a==='nav'){nav=id;render();window.scrollTo(0,0)}if(a==='task-filter'){taskFilter=id;render()}if(a==='all-tasks'){nav='tasks';taskFilter='全部';render()}if(a==='post-filter'){postFilter=id;render()}if(a==='task')openTask(id);if(a==='new-task')taskForm();if(a==='edit-task')taskForm(id);if(a==='draft'){try{localStorage.setItem('draft-'+id,$('#submission-text').value);toast('草稿已保存')}catch{toast('草稿保存失败，浏览器存储空间不足')}}if(a==='new-post')postForm();if(a==='edit-post'){const p=data.posts.find(p=>p.id===id);if(p?.user===user())postForm(id)}if(a==='post')openPost(id);if(a==='like'||a==='like-modal'){const p=data.posts.find(p=>p.id===id);p.likes=p.likes.includes(user())?p.likes.filter(x=>x!==user()):[...p.likes,user()];save();render();if(a==='like-modal')openPost(id)}if(a==='pin'){const p=data.posts.find(p=>p.id===id);p.pinned=!p.pinned;save();render();openPost(id)}if(a==='delete-post'){const p=data.posts.find(p=>p.id===id);if(p.user===user()||isTeacher())confirmDelete('这篇帖子','confirm-post-delete',id)}if(a==='confirm-post-delete'){data.posts=data.posts.filter(p=>p.id!==id||(p.user!==user()&&!isTeacher()));save();closeModal();render();toast('帖子已删除')}if(a==='delete-comment'){const [pid,cid]=id.split(':');const p=data.posts.find(p=>p.id===pid);p.comments=p.comments.filter(c=>c.id!==cid||(c.user!==user()&&!isTeacher()));save();render();openPost(pid)}if(a==='announcements')announcements();if(a==='notice'){const n=data.announcements.find(n=>n.id===id);modal('社团公告',`<h2>${esc(n.title)}</h2><div class="muted">${fmt(n.time)} · 指导教师发布</div><p>${esc(n.body)}</p><div class="form-actions"><button class="secondary" data-action="announcements">全部公告</button></div>`)}if(a==='new-notice')noticeForm();if(a==='edit-notice')noticeForm(id);if(a==='delete-notice')confirmDelete('这条公告','confirm-notice-delete',id);if(a==='confirm-notice-delete'){data.announcements=data.announcements.filter(n=>n.id!==id);save();render();announcements();toast('公告已删除')}if(a==='review'){const [tid,sid]=id.split(':');const s=data.tasks.find(t=>t.id===tid).submissions.find(s=>s.id===sid);modal('评价任务提交',`<p><strong>${esc(s.name)}</strong> 的提交</p><p>${esc(s.text)}</p>${fileHTML(s.files)}<form id="review-form" data-id="${id}"><label>评价结果<select name="status"><option ${s.status==='已完成'?'selected':''}>已完成</option><option ${s.status==='需修改'?'selected':''}>需修改</option></select></label><label>教师反馈<textarea name="feedback" required maxlength="5000" placeholder="给学生一些具体的反馈和建议…">${esc(s.feedback||'')}</textarea></label><div class="form-actions"><button class="primary">保存评价</button></div></form>`)}if(a==='profile'){const p=profile();modal('个人资料',`<form id="profile-form"><label>姓名<input name="name" required maxlength="20" value="${esc(p.name)}"></label><label>班级 / 社团信息<input name="className" maxlength="50" value="${esc(p.className)}"></label><label>个人简介<textarea name="bio" maxlength="300">${esc(p.bio)}</textarea></label><div class="info-box">当前身份：${isTeacher()?'指导教师':'学生'}。身份切换请退出体验后重新选择。</div><div class="form-actions"><button type="button" class="secondary" data-action="exit-modal">退出体验</button><button class="primary">保存资料</button></div></form>`)}if(a==='exit-modal'){closeModal();role='';sessionStorage.removeItem('zhixing-role');render()}if(a==='download'){let found;for(const t of data.tasks)for(const s of t.submissions)found=found||(s.files||[]).find(f=>f.id===id);for(const p of data.posts)found=found||(p.files||[]).find(f=>f.id===id);if(found){const bytes=Uint8Array.from(atob(found.data.split(',')[1]),c=>c.charCodeAt(0));const url=URL.createObjectURL(new Blob([bytes],{type:'application/octet-stream'}));const link=document.createElement('a');link.href=url;link.download=found.name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,fields=new FormData(form),id=form.dataset.id,values=Object.fromEntries(fields.entries());const button=form.querySelector('button[type=submit],button.primary');const snapshot=JSON.stringify(data);if(button)button.disabled=true;try{if(Object.entries(values).some(([k,v])=>typeof v==='string'&&['title','text','body','name','feedback','category'].includes(k)&&!v.trim()))throw Error('请填写有效内容，不能只输入空格');
if(form.id==='submit-task'){if(isTeacher())return;const t=data.tasks.find(t=>t.id===id),old=submission(t),files=await readFiles(form.elements.files);if(old?.status==='待评价')old.status='已更新';t.submissions.push({id:uid(),user:user(),name:profile().name,text:values.text.trim(),files:files.length?files:old?.files||[],time:new Date().toISOString(),status:'待评价',feedback:''});if(!save()){data=JSON.parse(snapshot);return}localStorage.removeItem('draft-'+id);closeModal();render();toast('任务已提交，等待老师评价')}
if(form.id==='task-form'&&isTeacher()){const t=data.tasks.find(t=>t.id===id),v={title:values.title.trim(),category:values.category.trim(),due:values.due,body:values.body.trim()};if(t)Object.assign(t,v);else data.tasks.unshift({id:uid(),...v,submissions:[]});if(!save()){data=JSON.parse(snapshot);return}closeModal();render();toast('任务已发布')}
if(form.id==='post-form'){const p=data.posts.find(p=>p.id===id);if(p&&p.user!==user())return;const files=await readFiles(form.elements.files);if(p)Object.assign(p,{title:values.title.trim(),body:values.body.trim(),category:values.category,files:files.length?files:p.files||[]});else data.posts.unshift({id:uid(),title:values.title.trim(),body:values.body.trim(),category:values.category,author:profile().name,user:user(),teacher:isTeacher(),pinned:false,time:new Date().toISOString(),likes:[],comments:[],files});if(!save()){data=JSON.parse(snapshot);return}closeModal();render();toast('帖子已发布')}
if(form.id==='comment-form'){const p=data.posts.find(p=>p.id===id);p.comments.push({id:uid(),user:user(),name:profile().name,body:values.body.trim(),time:new Date().toISOString()});if(!save()){data=JSON.parse(snapshot);return}render();openPost(id);toast('评论已发布')}
if(form.id==='notice-form'&&isTeacher()){const n=data.announcements.find(n=>n.id===id),v={title:values.title.trim(),body:values.body.trim(),pinned:values.pinned==='true',time:new Date().toISOString()};if(n)Object.assign(n,v);else data.announcements.unshift({id:uid(),...v});if(!save()){data=JSON.parse(snapshot);return}render();announcements();toast('公告已发布')}
if(form.id==='review-form'&&isTeacher()){const [tid,sid]=id.split(':');const s=data.tasks.find(t=>t.id===tid).submissions.find(s=>s.id===sid);Object.assign(s,{status:values.status,feedback:values.feedback.trim()});if(!save()){data=JSON.parse(snapshot);return}render();openTask(tid);toast('评价已保存')}
if(form.id==='profile-form'){Object.assign(profile(),{name:values.name.trim(),className:values.className.trim(),bio:values.bio.trim()});if(!save()){data=JSON.parse(snapshot);return}closeModal();render();toast('个人资料已更新')}
}catch(error){data=JSON.parse(snapshot);toast(error.message||'操作未完成，请重试')}finally{if(button)button.disabled=false}});
window.addEventListener('storage',e=>{if(e.key==='zhixing-v1'&&e.newValue){try{data=JSON.parse(e.newValue);render()}catch{}}});
render();
